preprod-full-access:
path "preprod/data/*" {
  capabilities = ["create", "read", "update", "delete", "list"]
}

path "preprod/metadata/*" {
  capabilities = ["read", "delete", "list"]
}

path "preprod/data/auth-service/+/config" {
